-- +migrate Up
-- Proper Crucible live-update (marshalled py2.7 func_code) for
-- BillboardMgr.GenerateAdvert. The shipped client formats the advert URL with
-- '...billboard.asp?%s' % patch.GetWebRequestParameters(), which raises
-- TypeError: "not all arguments converted during string formatting". The
-- exception escapes Billboard::LateAssembleUpdate -> sm.GetService('billboard')
-- -> StartServiceAndWaitForRunningState, which blocks forever, so the space
-- scene never loads. The new func_code is exception-safe, avoids %-formatting,
-- tolerates a tuple/None and fetches OUR portal advert.
INSERT INTO liveupdates
  (updateID, updateName, description, machoVersionMin, machoVersionMax,
   buildNumberMin, buildNumberMax, methodName, objectID, codeType, code)
VALUES
  (7, 'BillboardAdvertFix',
   'safe BillboardMgr.GenerateAdvert (client TypeError hung the space scene)',
   0, 999999, 1, 500000, 'GenerateAdvert', 'svc.billboard::BillboardMgr', 'globalClassMethod',
   UNHEX(''))
ON DUPLICATE KEY UPDATE
  updateName=VALUES(updateName), description=VALUES(description),
  machoVersionMin=VALUES(machoVersionMin), machoVersionMax=VALUES(machoVersionMax),
  buildNumberMin=VALUES(buildNumberMin), buildNumberMax=VALUES(buildNumberMax),
  methodName=VALUES(methodName), objectID=VALUES(objectID),
  codeType=VALUES(codeType), code=VALUES(code);

-- +migrate Down
DELETE FROM liveupdates WHERE updateID=7;